CREATE TEMPORARY VIEW all_cspu_model_${grass_region_without_quote} AS
SELECT
     cspu_id
    ,model_id
    ,'80p80r' as cspu_pr_rate
from srdi_mart.dim_sr_data_warehouse_pb_all_cspu_link_analysis_hf
where grass_region in (${grass_region})  and local_date = ${local_date}
group by
     cspu_id
    ,model_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW order_${grass_region_without_quote} AS
SELECT
     order_model_id as model_id
    ,sum(order_fraction * atc_prorate * first_touchpoint_item) AS order_cnt
FROM traffic_omni_oa.dwd_order_item_atc_journey_di__reg_sensitive_live
WHERE grass_region IN (${grass_region}) AND grass_date = ${local_date} and tz_type='local'
group by
     order_model_id
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_cspu_level_1d partition (grass_region = ${grass_region},local_date = ${local_date})
select
     cspu_id
    ,coalesce(sum(order_cnt),0) as order_cnt
    ,max(cspu_pr_rate) as cspu_pr_rate
from all_cspu_model_${grass_region_without_quote} a
left join order_${grass_region_without_quote} b on a.model_id = b.model_id
group by
     cspu_id
